"""Minify the generated JavaScript for ``dist/`` output.

Both the hand-written ``workpeg-runtime.js`` and the compiled ``app.js`` are
readable in development; this strips their comments and whitespace when they
are written into a build so the distributed artifact is lean.

``rjsmin`` is a *safe* minifier — it removes comments and collapses
whitespace but never renames identifiers and leaves string/template/regex
literals untouched, so the output is behaviourally identical to the input.
If it is somehow unavailable the source is returned unchanged, so a build
never fails for want of a minifier.
"""
from __future__ import annotations

try:
    import rjsmin

    _jsmin = rjsmin.jsmin
except ImportError:  # pragma: no cover - rjsmin is a declared dependency
    _jsmin = None


#: Attribution banner kept on the minified runtime (app.js gets none).
RUNTIME_BANNER = "/* Workpeg runtime - https://gitlab.com/workpeg/workpeg-sdk (MIT) */"


def minify_js(source: str, *, banner: str | None = None) -> str:
    """Return *source* minified, optionally prefixed with a *banner* comment.

    Falls back to the unmodified source when rjsmin is not importable.
    """
    if _jsmin is None:
        return source
    out = _jsmin(source)
    if banner:
        out = banner.rstrip("\n") + "\n" + out
    return out


def minify_css(source: str) -> str:
    """Conservatively minify CSS: strip ``/* … */`` comments, indentation,
    trailing spaces, and blank lines — nothing else.

    Comment scanning is string-aware (a ``*/`` inside a quoted value, e.g. in
    a data URI, is content, not a terminator), and intra-line spacing is kept
    as-is because ``calc()`` and friends are whitespace-sensitive. The output
    is therefore behaviourally identical CSS, roughly a quarter smaller on a
    comment-heavy sheet.
    """
    out: list[str] = []
    i, n = 0, len(source)
    while i < n:
        c = source[i]
        if c == "/" and i + 1 < n and source[i + 1] == "*":
            end = source.find("*/", i + 2)
            i = n if end < 0 else end + 2
            continue
        if c in "\"'":
            end = i + 1
            while end < n and source[end] != c:
                end += 2 if source[end] == "\\" else 1
            out.append(source[i:end + 1])
            i = end + 1
            continue
        out.append(c)
        i += 1
    lines = (line.strip() for line in "".join(out).splitlines())
    return "\n".join(line for line in lines if line)


def main(argv: "list[str] | None" = None) -> int:
    """CLI: ``python src/workpeg/ui/minify.py <in> <out>`` — minify one asset.

    Picks the minifier from the input suffix (.css / .js). Runnable by file
    path with no package import and no dependencies (rjsmin is optional), so
    CI can minify the CDN assets in a bare python image before uploading.
    """
    import argparse
    from pathlib import Path

    ap = argparse.ArgumentParser(description=main.__doc__)
    ap.add_argument("src", type=Path)
    ap.add_argument("out", type=Path)
    args = ap.parse_args(argv)

    source = args.src.read_text(encoding="utf-8")
    if args.src.suffix == ".css":
        result = minify_css(source)
    elif args.src.suffix == ".js":
        # The LIBRARY falls back to unminified source, deliberately: a dev
        # build should not die for want of a minifier. The CLI must not,
        # because the only thing that runs it is the CDN publish, and there
        # the fallback is silent and permanent — it exits 0, the job goes
        # green, and every reader downloads the unminified bundle forever.
        # That is exactly what happened: `pip install awscli` in the publish
        # jobs never brought rjsmin, so ai.js and scaffold.js were served at
        # ~190 KB instead of ~102 KB, and came off the CDN LARGER than source
        # because the provenance banner was the only thing the step added.
        # CSS never showed it — minify_css is pure Python and always worked,
        # so pegment.css's 35% made the step look healthy.
        if _jsmin is None:
            print("refusing to write unminified JavaScript: rjsmin is not "
                  "importable. Install it (pip install rjsmin) — do not ship "
                  "the source as if it were minified.")
            return 3
        result = minify_js(source)
    else:
        print(f"unsupported asset type: {args.src.suffix}")
        return 2
    # newline="\n": the byte count printed below, and whatever hash the caller
    # takes of the result, must describe the file that lands on disk — the
    # default would translate the newlines on Windows and make both a fiction.
    args.out.write_text(result, encoding="utf-8", newline="\n")
    saved = 1 - (len(result) / len(source)) if source else 0
    print(f"{args.src.name}: {len(source):,} -> {len(result):,} bytes "
          f"({saved:.0%} smaller)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
